size_t N = 100;

// Allocate block of N integers (returns void*)
int* persistent_data = malloc(N * sizeof(int));

// Always check for allocation failure (Out of Memory)
if (persistent_data == NULL) {
    /* Error handling */
    return;
}

// Memory block persists beyond function scope
for (size_t i = 0; i < N; i++) {
    persistent_data[i] = (int)i;
}

// Must manually release allocated memory
free(persistent_data);
